fn mutate(row: {n: number | null}) { row.n = null }
const narrow = {n: 1}
mutate(narrow)

let wide: {n: number | null} = {n: 1}
wide = {n: 2}
const narrow: {n: number} = wide

export fn choose(row: {n: number} | null, flag: boolean): number {
  if flag { row = {n: 1} } else { row = {n: 2} }
  return row.n
}
export let value: number | null = 1
value = null
export fn read(): number { let n: number = 1; n += 2; return n }

const row = {n: 1}
const get = fn(): {n: number} => row
const widened: fn(): {n: number | null} = get

use std "decimal" as d
const amount: string = d.quantize(d.add("0.1", "0.2"), 2, "half-even")
const n: number = d.toNumber(amount)

export fn maybe(flag: boolean) { if flag { return 1 } }
export fn caught(): number { try { throw "failure" } catch err { return 2 } }
export fn overridden() { try { return 1 } finally { return "final" } }
export fn defaulted(a: number = 1, b: number): number => a + b
fn count(...values: number[]): number => values.length
const values: number[] = [1, 2]
export const copy: number[] = [...values, 3]
export const size: number = count(...values)
